  const el = links.nth(i);
  const href = await el.getAttribute("href");
  const txt = (await el.innerText()).replace(/\s+/g, " ");
  out.push({ href, txt });
}
const uniq = [];
const seen = new Set();
for (const o of out) {
  const key = (o.href || "").match(/(\d{6,})/)?.[1] ?? o.href;
  if (seen.has(key)) continue;
  seen.add(key);
  uniq.push(o);
}
nodeRepl.write(JSON.stringify({ total: cnt, unique: uniq.length, items: uniq }, null, 1));
