{"code": "const browserPluginRoot =
  process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import("node:path");
const { pathToFileURL } = await import("node:url");
const browserClientUrl = pathToFileURL(
  join(browserPluginRoot, "scripts", "browser-client.mjs"),
).href;
const { setupBrowserRuntime } = await import(browserClientUrl);
await setupBrowserRuntime({ globals: globalThis });

const browser = await agent.browsers.get("iab");
const tab = await browser.tabs.get("iab-tab:f254e19c-bd0d-4e12-9f65-e1fa7e5d9624");

async function grab() {
  const links = tab.playwright.locator('a[href*="/complaint/view/"]');
  const cnt = await links.count();
  const out = [];
  for (let i = 0; i < cnt; i++) {
    const el = links.nth(i);
    const txt = (await el.innerText()).replace(/\s+/g, " ");
    out.push(txt);
  }
  return out;
}

let all = [];
for (let step = 0; step < 14; step++) {
  await tab.cua.scroll({ x: 640, y: 400, scrollX: 0, scrollY: 2600 });
  await tab.playwright.waitForTimeout(900);
  const now = await grab();
  if (now.length > all.length) all = now;
  if (all.length >= 80) break;
}
const uniq = [];
const seen = new Set();
for (const t of all) {
  const d = (t.match(/\d{4}-\d{2}-\d{2}/) || [""])[0];
  const h = (t.match(/发起\s*([^\[]+)/) || ["", t])[1].trim();
  const key = d + "|" + h;
  if (seen.has(key)) continue;
  seen.add(key);
  uniq.push({ d, h });
}
nodeRepl.write(JSON.stringify({ loaded: all.length, unique: uniq.length }, null, 1));
nodeRepl.write("\n" + uniq.map((u, i) => (i + 1) + ". [" + u.d + "] " + u.h).join("\n"));
", "title": "滚动加载全部投诉记录"}

